public static void parseDefine(final Define d, final ParsedDefine p)
			throws MojoExecutionException {
		parseDefineName(d.getDefineName(), p);
		parseDefineValueType(d.getValueType(), p);
		parseDefineValue(d.getValue(), p);
	}
